class Solution {
public:
    bool isAdditiveNumber(string num) {
        int n = num.size();
        for (int i = 1; i <= n / 2; ++i) {
            if (num[0] == '0' && i > 1) break;
            for (int j = 1; n - i - j >= max(i, j); ++j) {
                if (num[i] == '0' && j > 1) break;
                string s1 = num.substr(0, i);
                string s2 = num.substr(i, j);
                size_t k = i + j;
                while (k < num.size()) {
                    string s3 = addStrings(s1, s2);
                    if (num.compare(k, s3.size(), s3) != 0) break;
                    k += s3.size();
                    s1 = s2;
                    s2 = s3;
                }
                if (k == num.size()) return true;
            }
        }
        return false;
    }

private:
    string addStrings(const string& a, const string& b) {
        string res = "";
        int i = a.size() - 1, j = b.size() - 1, carry = 0;
        while (i >= 0 || j >= 0 || carry) {
            int sum = carry;
            if (i >= 0) sum += a[i--] - '0';
            if (j >= 0) sum += b[j--] - '0';
            carry = sum / 10;
            res.push_back((sum % 10) + '0');
        }
        reverse(res.begin(), res.end());
        return res;
    }
};

class Solution {
    public boolean isAdditiveNumber(String num) {
        int n = num.length();
        for (int i = 1; i <= n / 2; i++) {
            if (num.charAt(0) == '0' && i > 1) break;
            for (int j = 1; n - i - j >= Math.max(i, j); j++) {
                if (num.charAt(i) == '0' && j > 1) break;
                String s1 = num.substring(0, i);
                String s2 = num.substring(i, i + j);
                int k = i + j;
                while (k < n) {
                    String s3 = add(s1, s2);
                    if (!num.startsWith(s3, k)) break;
                    k += s3.length();
                    s1 = s2;
                    s2 = s3;
                }
                if (k == n) return true;
            }
        }
        return false;
    }

    private String add(String a, String b) {
        StringBuilder sb = new StringBuilder();
        int i = a.length() - 1, j = b.length() - 1, carry = 0;
        while (i >= 0 || j >= 0 || carry > 0) {
            int sum = carry;
            if (i >= 0) sum += a.charAt(i--) - '0';
            if (j >= 0) sum += b.charAt(j--) - '0';
            carry = sum / 10;
            sb.append(sum % 10);
        }
        return sb.reverse().toString();
    }
}

